import{_ as o,c as e,o as t,aj as a}from"./chunks/framework.B-K7myP5.js";const h=JSON.parse('{"title":"如何使用脚本安装 Composer？","frontmatter":{"title":"如何使用脚本安装 Composer？","createTime":"2025/01/17 19:27:31","permalink":"/docs/composer/to-install-composer-programmatically.html","lastUpdated":"2026-01-22","tags":[],"link":"/docs/composer/常见问题/to-install-composer-programmatically","layout":"doc","sidebar":true,"aside":true,"prev":{"text":"如何为我的框架自定义一个扩展包安装目录？","link":"/docs/composer/index"},"next":{"text":"使用 root 用户来安装扩展包是否安全？如何安全地安装未认证渠道的扩展包？","link":"/docs/composer/常见问题/to-install-untrusted-packages-safely"}},"headers":[],"params":{"pkg":"composer/常见问题/to-install-composer-programmatically","sidebar":[{"text":"常见问题","items":[{"text":"如何为我的框架自定义一个扩展包安装目录？","link":"/docs/composer/index"},{"text":"如何使用脚本安装 Composer？","link":"/docs/composer/常见问题/to-install-composer-programmatically"},{"text":"使用 root 用户来安装扩展包是否安全？如何安全地安装未认证渠道的扩展包？","link":"/docs/composer/常见问题/to-install-untrusted-packages-safely"},{"text":"我应该将 vendor 目录加入版本控制吗？","link":"/docs/composer/常见问题/i-commit-the-dependencies-in-my-vendor-directory"},{"text":"Composer 使用的是什么版本命名规范？","link":"/docs/composer/常见问题/version-numbering-system-does-composer-itself-use"},{"text":"为什么限制版本是最佳实践？","link":"/docs/composer/常见问题/are-unbound-version-constraints-a-bad-idea"},{"text":"为何版本限制与对比符、通配符配合使用是个糟糕的行为？","link":"/docs/composer/常见问题/are-version-constraints-combining-comparisons-and-wildcards-a-bad-idea"},{"text":"为什么 Composer 不递归加载代码库？","link":"/docs/composer/常见问题/cant-composer-load-repositories-recursively"}]},{"text":"官方文章","items":[{"text":"分支别名","link":"/docs/composer/官方文章/aliases"},{"text":"版本限制","link":"/docs/composer/官方文章/versions"},{"text":"自动加载器优化","link":"/docs/composer/官方文章/optimization"},{"text":"自定义安装器","link":"/docs/composer/官方文章/installers"},{"text":"使用 Satis 处理私有仓库","link":"/docs/composer/官方文章/private-packages-with-satis"},{"text":"HTTP 基础认证","link":"/docs/composer/官方文章/basic-authentication"},{"text":"创建 Composer 插件","link":"/docs/composer/官方文章/plugins"},{"text":"事件和自定义脚本","link":"/docs/composer/官方文章/scripts"},{"text":"故障排除","link":"/docs/composer/官方文章/troubleshooting"},{"text":"可执行二进制文件","link":"/docs/composer/官方文章/binaries"}]},{"text":"教程","items":[{"text":"简介","link":"/docs/composer/教程/intro"},{"text":"基本使用","link":"/docs/composer/教程/basic-usage"},{"text":"创建扩展包","link":"/docs/composer/教程/libraries"},{"text":"Composer 命令的使用","link":"/docs/composer/教程/cli"},{"text":"json 完全解析","link":"/docs/composer/教程/schema"},{"text":"扩展包源仓库","link":"/docs/composer/教程/repositories"},{"text":"配置信息","link":"/docs/composer/教程/config"},{"text":"社区","link":"/docs/composer/教程/community"}]}],"versions":[]},"relativePath":"docs/composer/常见问题/to-install-composer-programmatically.md","filePath":"docs/[pkg].md"}'),n={name:"docs/composer/常见问题/to-install-composer-programmatically.md"};function p(i,s,r,c,l,m){return t(),e("div",null,[...s[0]||(s[0]=[a(`<h1 id="我们如何以编程的方式安装-composer" tabindex="-1">我们如何以编程的方式安装 Composer? <a class="header-anchor" href="#我们如何以编程的方式安装-composer" aria-label="Permalink to “我们如何以编程的方式安装 Composer?”">​</a></h1><p>如下载页面所指出的，这个安装程序包含一个签名,当安装程序代码发生改变时,它会随之发生改变,因此不应该长期依赖。 还有另一种方法，就是使用只对 UNIX 实用程序工作的脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>EXPECTED_SIGNATURE=&quot;$(wget -q -O - https://composer.github.io/installer.sig)&quot;</span></span>
<span class="line"><span>php -r &quot;copy(&#39;https://getcomposer.org/installer&#39;, &#39;composer-setup.php&#39;);&quot;</span></span>
<span class="line"><span>ACTUAL_SIGNATURE=&quot;$(php -r &quot;echo hash_file(&#39;SHA384&#39;, &#39;composer-setup.php&#39;);&quot;)&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ &quot;$EXPECTED_SIGNATURE&quot; != &quot;$ACTUAL_SIGNATURE&quot; ]</span></span>
<span class="line"><span>then</span></span>
<span class="line"><span>    &gt;&amp;2 echo &#39;ERROR: Invalid installer signature&#39;</span></span>
<span class="line"><span>    rm composer-setup.php</span></span>
<span class="line"><span>    exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>php composer-setup.php --quiet</span></span>
<span class="line"><span>RESULT=$?</span></span>
<span class="line"><span>rm composer-setup.php</span></span>
<span class="line"><span>exit $RESULT</span></span></code></pre></div><p>如果失败，脚本将退出并返回1，或者成功返回0，如果没有任何返回则是没有错误。</p><p>或者，如果你想使用这个安装程序副本安装，你可以从 GitHub 的历史中获取特定的版本。如果您足够信任 GitHub 服务器，提交hash就足以让它具有唯一性和真实性。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wget https://raw.githubusercontent.com/composer/getcomposer.org/1b137f8bf6db3e79a38a5bc45324414a6b1f9df2/web/installer -O - -q | php -- --quiet</span></span></code></pre></div><p>你可以在最后一次提交的基础上提交替换任何内容的 hash： <a href="https://github.com/composer/getcomposer.org/commits/master" target="_blank" rel="noreferrer">https://github.com/composer/getcomposer.org/commits/master</a></p>`,7)])])}const u=o(n,[["render",p]]);export{h as __pageData,u as default};
